<?php
require 'config.php';require_login();
$truck=db()->query("SELECT t.id,t.unit_no,COALESCE((SELECT SUM(rate) FROM loads l WHERE l.truck_id=t.id AND l.status IN ('Delivered','Invoiced','Paid')),0) revenue,COALESCE((SELECT SUM(amount) FROM expenses e WHERE e.truck_id=t.id),0) expenses,COALESCE((SELECT SUM(p.net_pay) FROM payroll p JOIN drivers d ON d.id=p.driver_id WHERE d.truck_id=t.id),0) payroll FROM trucks t ORDER BY t.unit_no")->fetchAll();
$loads=db()->query("SELECT l.id,l.load_no,l.rate,COALESCE((SELECT SUM(amount) FROM expenses e WHERE e.load_id=l.id),0) expenses,COALESCE((SELECT SUM(p.net_pay) FROM payroll p WHERE p.driver_id=l.driver_id AND p.week_start<=COALESCE(l.delivery_date,CURDATE()) AND p.week_end>=COALESCE(l.delivery_date,CURDATE())),0) driver_pay FROM loads l ORDER BY l.id DESC")->fetchAll();
$tot=db()->query("SELECT COALESCE(SUM(rate),0) FROM loads WHERE status IN ('Delivered','Invoiced','Paid')")->fetchColumn();$exp=db()->query("SELECT COALESCE(SUM(amount),0) FROM expenses")->fetchColumn();$pay=db()->query("SELECT COALESCE(SUM(net_pay),0) FROM payroll")->fetchColumn();$fact=db()->query("SELECT COALESCE(SUM(fee),0) FROM factoring")->fetchColumn();$pageTitle='Profit & Loss';$active='reports';require 'partials_header.php';?>
<div class="page-head"><div><h1>Profit & loss reporting</h1><p>Review revenue, expenses and driver payroll by truck and by load.</p></div></div><div class="cards"><?php foreach([['Delivered revenue',$tot],['Operating expenses',$exp],['Driver net payroll',$pay],['Factoring fees',$fact]] as $x):?><div class="stat"><div class="stat-top"><?=e($x[0])?></div><div class="stat-value"><?=money($x[1])?></div></div><?php endforeach;?></div><div class="panel"><h3>Estimated company net</h3><div class="stat-value" style="color:#58d9a8"><?=money((float)$tot-(float)$exp-(float)$pay-(float)$fact)?></div><p class="muted">Delivered revenue less recorded operating expenses, driver net payroll and factoring fees. This is a management estimate, not audited accounting.</p></div>
<div class="panel"><h3>Profit & loss by truck</h3><div class="table-wrap"><table class="table"><thead><tr><th>Truck</th><th>Revenue</th><th>Expenses</th><th>Driver payroll</th><th>Estimated net</th></tr></thead><tbody><?php foreach($truck as $r):?><tr><td><?=e($r['unit_no'])?></td><td><?=money($r['revenue'])?></td><td><?=money($r['expenses'])?></td><td><?=money($r['payroll'])?></td><td><strong><?=money($r['revenue']-$r['expenses']-$r['payroll'])?></strong></td></tr><?php endforeach;?><?php if(!$truck):?><tr><td colspan="5" class="empty">No truck data.</td></tr><?php endif;?></tbody></table></div></div>
<div class="panel"><h3>Profit & loss by load</h3><div class="table-wrap"><table class="table"><thead><tr><th>Load</th><th>Revenue</th><th>Expenses</th><th>Driver pay (period estimate)</th><th>Estimated net</th></tr></thead><tbody><?php foreach($loads as $r):?><tr><td><?=e($r['load_no'])?></td><td><?=money($r['rate'])?></td><td><?=money($r['expenses'])?></td><td><?=money($r['driver_pay'])?></td><td><strong><?=money($r['rate']-$r['expenses']-$r['driver_pay'])?></strong></td></tr><?php endforeach;?><?php if(!$loads):?><tr><td colspan="5" class="empty">No load data.</td></tr><?php endif;?></tbody></table></div></div><?php require 'partials_footer.php';?>